      author_name: 'G.Sathyanarayana Raju.Peetla.',
      content: `এই প্রত্নতাত্ত্বিক সংগ্রহটি হাতিগুম্ফা শিলালিপি, কেন্দুপাটনা ও ভেলিগলানি তাম্রশাসন এবং বারাবাটি ও কোল্লেটিকোটা দুর্গের প্রমাণ উপস্থাপন করে।`
