      content: `ఈ చారిత్రక అట్లాస్ మహానది, గోదావరి, కృష్ణా, పెన్నా మరియు కావేరి నదీ లోయల మధ్య ఉన్న బారాబతి (కటక్), కళింగనగరం, సింహాచలం, రాజమహేంద్రవరం, కొల్లేటికోట (జలదుర్గం), కొండపల్లి, కొండవీడు మరియు ఉదయగిరి కోటల భౌగోళిక మరియు సైనిక నెట్‌వర్క్‌ను వివరిస్తుంది.`
